package com.gymmind.ai.application;
import com.gymmind.ai.domain.ContextSegment; import com.gymmind.knowledge.application.KnowledgeSearchService; import com.gymmind.shared.error.*; import com.gymmind.shared.security.CurrentActor; import java.util.*; import org.springframework.stereotype.Service;
@Service public class DefaultAiChatService implements AiChatService { private final KnowledgeSearchService search; private final ChatModelGateway model; public DefaultAiChatService(KnowledgeSearchService s,ChatModelGateway m){search=s;model=m;} public AiChatView chat(CurrentActor a,String session,String q){if(a==null||a.tenantId()==null||!a.hasPermission("ai:chat"))throw new BusinessException(ErrorCode.FORBIDDEN);if(session==null||session.isBlank()||q==null||q.isBlank())throw new BusinessException(ErrorCode.VALIDATION_FAILED);List<ContextSegment> c=search.search(a,q);if(c==null||c.isEmpty())return new AiChatView("没有找到足够可靠的知识依据，暂不提供确定性建议。",List.of());return new AiChatView(model.complete(q,c),c.stream().map(ContextSegment::id).filter(Objects::nonNull).distinct().toList());} }
